<?php $pageTitle='Ajukan Pengembalian'; ob_start(); if(empty($_SESSION['csrf_token']))$_SESSION['csrf_token']=bin2hex(random_bytes(32)); ?>
<div class="max-w-6xl mx-auto px-4 py-8"><a href="<?=url('/returns')?>" class="text-blue-600">← Kembali</a><h1 class="text-3xl font-bold mt-3 mb-1">Ajukan Pengembalian</h1><p class="text-sm text-gray-500 mb-6">Pilih peminjaman yang masih aktif, lalu pilih barang yang benar-benar dikembalikan.</p>
<?php if(isset($_SESSION['error'])):?><div class="mb-4 bg-red-50 border border-red-200 text-red-700 p-3 rounded-lg"><?=htmlspecialchars($_SESSION['error']);unset($_SESSION['error']);?></div><?php endif;?>
<form method="POST" action="<?=url('/returns/store')?>" class="space-y-6"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars($_SESSION['csrf_token'])?>"><div class="bg-white rounded-xl shadow p-6"><div class="grid md:grid-cols-2 gap-5"><div><label class="block text-sm font-semibold mb-1">Peminjaman</label><select name="loan_id" id="loan_id" required class="w-full border rounded-lg px-3 py-2"><option value="">Pilih Peminjaman Aktif</option><?php foreach($loans as $l):?><option value="<?=$l['id']?>">Peminjaman - <?=htmlspecialchars($l['warehouse_name'])?></option><?php endforeach;?></select></div><div><label class="block text-sm font-semibold mb-1">Gudang Tujuan</label><select name="warehouse_id" required class="w-full border rounded-lg px-3 py-2"><option value="">Pilih Gudang</option><?php foreach($warehouses as $w):?><option value="<?=$w['id']?>"><?=htmlspecialchars($w['name'])?></option><?php endforeach;?></select></div><div class="md:col-span-2"><label class="block text-sm font-semibold mb-1">Catatan</label><textarea name="notes" rows="2" class="w-full border rounded-lg px-3 py-2"></textarea></div></div></div>
<div class="bg-white rounded-xl shadow p-6"><h2 class="text-lg font-semibold mb-4">Barang yang Dikembalikan</h2><div id="empty" class="text-center text-gray-500 py-8">Pilih peminjaman untuk memuat barang.</div><div class="overflow-x-auto"><table id="tbl" class="w-full min-w-[800px] lg:min-w-full hidden"><thead class="bg-gray-50"><tr><th class="p-3 text-left">Barang</th><th class="p-3">Sisa</th><th class="p-3">Jumlah</th><th class="p-3 text-left">Serial Number</th></tr></thead><tbody id="body"></tbody></table></div></div><div class="flex justify-end gap-3"><a href="<?=url('/returns')?>" class="px-5 py-2 rounded-lg bg-gray-100">Batal</a><button class="px-5 py-2 rounded-lg bg-blue-600 text-white font-semibold">Kirim Pengembalian</button></div></form></div>
<script>let data=[];const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const load=async()=>{const id=document.getElementById('loan_id').value;const body=document.getElementById('body');body.innerHTML='';if(!id){document.getElementById('tbl').classList.add('hidden');document.getElementById('empty').classList.remove('hidden');return;}try{const r=await fetch(`<?=url('/returns/api/items')?>?loan_id=${encodeURIComponent(id)}`);data=await r.json();if(!data.length){document.getElementById('tbl').classList.add('hidden');document.getElementById('empty').classList.remove('hidden');document.getElementById('empty').textContent='Tidak ada barang yang masih dapat dikembalikan.';return;}document.getElementById('empty').classList.add('hidden');document.getElementById('tbl').classList.remove('hidden');data.forEach((x,i)=>{const tr=document.createElement('tr');tr.className='border-t';const serial=x.serials||[];tr.innerHTML=`<td class="p-3"><input type="hidden" name="source_types[${i}]" value="${x.source_type}"><input type="hidden" name="loan_item_ids[${i}]" value="${x.loan_item_id||''}"><input type="hidden" name="manual_item_ids[${i}]" value="${x.manual_item_id||''}"><div class="font-medium">${esc(x.nama)}</div>${x.source_type==='MANUAL'?'<div class="text-xs text-amber-600">Manual / Custom</div>':''}</td><td class="p-3 text-center">${x.remaining_quantity}</td><td class="p-3"><input id="qty-${i}" name="quantities[${i}]" type="number" min="1" max="${x.remaining_quantity}" value="1" class="w-24 border rounded-lg px-2 py-2 text-center"></td><td class="p-3">${x.is_serialized?`<select id="sn-${i}" name="serial_ids[${i}][]" multiple size="4" class="w-full border rounded-lg px-2 py-2">${serial.map(s=>`<option value="${s.id}">${esc(s.serial_number)}</option>`).join('')}</select><div class="text-xs text-gray-500 mt-1">Pilih serial yang benar-benar dikembalikan.</div>`:'<span class="italic text-gray-400">Barang bulk</span>'}</td>`;body.appendChild(tr);if(x.is_serialized){const sel=tr.querySelector(`#sn-${i}`),qty=tr.querySelector(`#qty-${i}`);sel.addEventListener('change',()=>qty.value=sel.selectedOptions.length||1);qty.addEventListener('input',()=>{if(+qty.value<1)qty.value=1;if(+qty.value>x.remaining_quantity)qty.value=x.remaining_quantity;const chosen=[...sel.options].filter(o=>o.selected).slice(0,+qty.value);[...sel.options].forEach(o=>o.selected=chosen.includes(o));});}});}catch(e){document.getElementById('empty').classList.remove('hidden');document.getElementById('empty').textContent='Gagal memuat barang peminjaman.';}};document.getElementById('loan_id').addEventListener('change',load);</script><?php $content=ob_get_clean();require __DIR__.'/../../layouts/app.php'; ?>